def min_groups(nums):
    from collections import Counter
    import math

    count = Counter(nums)

    min_freq = min(count.values())

    def can_divide(freq, size):
        groups = freq // size
        remainder = freq % size
        if remainder == 0:
            return groups
        if remainder <= groups:
            return groups + 1
        return float('inf')

    best_total = float('inf')

    for size in range(1, min_freq + 1):
        total_groups = 0
        possible = True
        for freq in count.values():
            g = can_divide(freq, size)
            if g == float('inf'):
                possible = False
                break
            total_groups += g
        if possible:
            best_total = min(best_total, total_groups)

    return best_total
```

