    for _ in range(N):
        a, b = map(int, sys.stdin.readline().split())
        tiles.append((a, b))

    # Grid to track covered cells
    grid = [[0] * W for _ in range(H)]

    def can_place(x, y, h, w):
        """Check if a tile of size hxw can be placed at position (x,y)"""
        if x + h > H or y + w > W:
            return False
        for i in range(x, x + h):
            for j in range(y, y + w):
                if grid[i][j] != 0:
                    return False
        return True

    def place_tile(x, y, h, w, val):
        """Place or remove a tile at position (x,y)"""
        for i in range(x, x + h):
            for j in range(y, y + w):
                grid[i][j] = val

    def find_empty():
        """Find the first empty cell"""
        for i in range(H):
            for j in range(W):
                if grid[i][j] == 0:
                    return i, j
        return None

    def backtrack(tile_idx, used):
        """Try to fill the grid using remaining tiles"""
        pos = find_empty()
        if pos is None:
            return True

        x, y = pos

        for i in range(N):
            if used[i]:
