def max_prime_gap(nums):
    """
    Returns the maximum distance between the indices of two prime numbers in nums.
    """
    # Helper to check if a number is prime
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    first_prime_index = None
    last_prime_index = None

    for i, num in enumerate(nums):
        if is_prime(num):
            if first_prime_index is None:
                first_prime_index = i
            last_prime_index = i

    # At least one prime is guaranteed
    return last_prime_index - first_prime_index
```

