def permutation_difference(s: str, t: str) -> int:
    # Create a dictionary to map each character to its index in s
    index_map_s = {char: idx for idx, char in enumerate(s)}

    # Create a dictionary to map each character to its index in t
    index_map_t = {char: idx for idx, char in enumerate(t)}

    # Calculate the total permutation difference
    total_difference = 0
    for char in s:
        total_difference += abs(index_map_s[char] - index_map_t[char])

    return total_difference
